// the first that fits by place in the list (the page's order), whatever the order of the rows here
const hit = (q) => { const out = { e: null, a: null };
  for (const [k, i, re, en, it, mood] of KNOW) if ((!out[k] || i < out[k].i) && re.test(q)) out[k] = en === null ? { i, trick: true } : { i, en, it, mood };
  return out; };

export async function onRequestPost({ request }) {
  let q = "";
  try { const b = await request.json(); q = String((b && b.q) || "").slice(0, 400); } catch (e) {}
  return new Response(JSON.stringify(q ? hit(q) : { e: null, a: null }), { headers: { "content-type": "application/json; charset=utf-8", "cache-control": "no-store" } });
}

export { hit };
